public class PureBudgetCalcTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        List<Integer> salaries = new ArrayList<>(Arrays.asList(1000, 2500));
        List<Integer> result = PureBudgetCalc.applyRaise(salaries, 10);

        check("applyRaise([1000, 2500], 10)", "[1100, 2750]", String.valueOf(result));
        check("input list unchanged", "[1000, 2500]", salaries.toString());
        check("runningTotal untouched", 0, PureBudgetCalc.runningTotal);
        check("result is a different object", false, result == salaries);

        List<Integer> again = PureBudgetCalc.applyRaise(salaries, 10);
        check("same arguments give the same answer", "[1100, 2750]", String.valueOf(again));
        check("still no shared state written", 0, PureBudgetCalc.runningTotal);

        List<Integer> zeroPercent = new ArrayList<>(Arrays.asList(700));
        List<Integer> copy = PureBudgetCalc.applyRaise(zeroPercent, 0);
        check("percent 0 keeps the values", "[700]", String.valueOf(copy));
        check("percent 0 still returns a new list", false, copy == zeroPercent);

        check("applyRaise(empty, 25)", "[]", String.valueOf(PureBudgetCalc.applyRaise(new ArrayList<>(), 25)));
        check("totalAfterRaise([1000, 2500], 10)", 3850, PureBudgetCalc.totalAfterRaise(salaries, 10));
        check("totalAfterRaise leaves input alone", "[1000, 2500]", salaries.toString());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
