import java.util.ArrayList;
import java.util.List;

/**
 * TASK: Replace a side-effecting routine with a PURE function.
 *
 * The old version looked like this and was a bug factory:
 *
 *     public static int runningTotal = 0;
 *     public static void applyRaise(List<Integer> salaries, int percent) {
 *         for (int i = 0; i < salaries.size(); i++) {
 *             int raised = salaries.get(i) + salaries.get(i) * percent / 100;
 *             salaries.set(i, raised);      // mutates the caller's list
 *             runningTotal += raised;       // mutates shared static state
 *         }
 *     }
 *
 * Write applyRaise so that it:
 *   - returns a NEW list of raised salaries (integer maths: salary + salary * percent / 100),
 *   - leaves the argument list byte-for-byte unchanged,
 *   - never assigns to runningTotal,
 *   - gives the same answer every time it is called with the same arguments.
 *
 * Example: applyRaise([1000, 2500], 10) -> [1100, 2750]
 * EDGE CASE: a percent of 0 returns a copy with the same numbers, not the same list object.
 */
public class PureBudgetCalc {

    /** Shared state left over from the old design. A pure function must never touch it. */
    public static int runningTotal = 0;

    public static List<Integer> applyRaise(List<Integer> salaries, int percent) {
        List<Integer> raised = new ArrayList<>();
        for (int salary : salaries) {
            raised.add(salary + salary * percent / 100);
        }
        return raised;
    }

    public static int totalAfterRaise(List<Integer> salaries, int percent) {
        int total = 0;
        for (int salary : applyRaise(salaries, percent)) {
            total += salary;
        }
        return total;
    }
}
